function epca_e(mixed $v): string { return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); }
function epca_scalar(string $sql,array $params=[],mixed $default=0): mixed { try{$s=db()->prepare($sql);$s->execute($params);$v=$s->fetchColumn();return $v===false?$default:$v;}catch(Throwable $e){return $default;} }
function epca_rows(string $sql,array $params=[]): array { try{$s=db()->prepare($sql);$s->execute($params);return $s->fetchAll()?:[];}catch(Throwable $e){return [];} }
function epca_mask(string $token): string { $token=trim($token);return $token===''?'—':substr($token,0,5).'…'.substr($token,-4); }
function epca_map(float $lat,float $lon): string { return 'https://www.openstreetmap.org/?mlat='.rawurlencode((string)$lat).'&mlon='.rawurlencode((string)$lon).'#map=15/'.$lat.'/'.$lon; }
function epca_online(?string $value,int $seconds=900): bool { if(!$value)return false;$t=strtotime($value);return $t!==false&&time()-$t<=$seconds; }
function epca_event_label(string $type): string { return ['pothole'=>'BURACO','animal'=>'ANIMAL','accident'=>'ACIDENTE','construction'=>'OBRA','flooding'=>'ALAGAMENTO','traffic'=>'TRÂNSITO','object'=>'OBJETO'][$type]??strtoupper($type); }
function epca_status_class(string $s): string { $s=strtoupper($s);return in_array($s,['ATIVO','ACTIVE','CONFIRMADO','OK','LIVRE'],true)?'ok':(in_array($s,['PENDENTE','ATENÇÃO','WARN','MODERADO','LENTO'],true)?'warn':'bad'); }

$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    require_csrf();$action=(string)($_POST['action']??'');
    try{
        if($action==='toggle_client'){
            $id=(int)($_POST['client_id']??0);$s=db()->prepare("UPDATE users SET status=CASE WHEN status='active' THEN 'inactive' ELSE 'active' END,updated_at=CURRENT_TIMESTAMP WHERE id=? AND role='client'");$s->execute([$id]);audit_log('epc_admin.client_toggle',['client_id'=>$id]);$message='Status do usuário atualizado.';
        }elseif($action==='reset_password'){
            $id=(int)($_POST['client_id']??0);$password=(string)($_POST['new_password']??'');if(strlen($password)<6)throw new RuntimeException('A nova senha precisa ter pelo menos 6 caracteres.');$s=db()->prepare("UPDATE users SET password_hash=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND role='client'");$s->execute([password_hash($password,PASSWORD_DEFAULT),$id]);audit_log('epc_admin.password_reset',['client_id'=>$id]);$message='Senha redefinida.';
        }elseif($action==='report_status'){
            $id=(int)($_POST['report_id']??0);$status=strtoupper((string)($_POST['status']??''));if(!intelligent_server_set_report_status($id,$status,(int)$admin['id']))throw new RuntimeException('Não foi possível atualizar esse relato.');$message='Relato atualizado para '.$status.'.';
        }elseif($action==='delete_live_event'){
            $id=(int)($_POST['event_id']??0);db()->beginTransaction();try{$s=db()->prepare('DELETE FROM road_live_votes WHERE event_id=?');$s->execute([$id]);if(schema_columns('road_live_confirmations')){$s=db()->prepare('DELETE FROM road_live_confirmations WHERE event_id=?');$s->execute([$id]);}$s=db()->prepare('DELETE FROM road_live_events WHERE id=?');$s->execute([$id]);db()->commit();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}audit_log('epc_admin.live_event_delete',['event_id'=>$id]);$message='Alerta comunitário removido.';
        }elseif($action==='delete_fuel'){
            $id=(int)($_POST['fuel_id']??0);$s=db()->prepare('DELETE FROM fuel_price_reports WHERE id=?');$s->execute([$id]);audit_log('epc_admin.fuel_delete',['fuel_id'=>$id]);$message='Preço de combustível removido.';
        }elseif($action==='close_convoy'){
            $id=(int)($_POST['convoy_id']??0);db()->beginTransaction();try{$s=db()->prepare('DELETE FROM estrada_convoy_members WHERE convoy_id=?');$s->execute([$id]);$s=db()->prepare('DELETE FROM estrada_convoys WHERE id=?');$s->execute([$id]);db()->commit();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}audit_log('epc_admin.convoy_close',['convoy_id'=>$id]);$message='Comboio encerrado.';
        }elseif($action==='housekeeping'){
            $r=intelligent_server_housekeeping(true);audit_log('epc_admin.housekeeping',['deleted'=>(int)($r['deleted']??0)]);$message='Manutenção executada. Registros expirados removidos: '.(int)($r['deleted']??0).'.';
        }elseif($action==='clear_weather'){
            $s=db()->prepare('DELETE FROM road_weather_cache');$s->execute();audit_log('epc_admin.weather_cache_clear',['deleted'=>$s->rowCount()]);$message='Cache meteorológico limpo.';
        }
    }catch(Throwable $e){$error=$e->getMessage()?:'Não foi possível concluir a ação.';}
}

$now=date('Y-m-d H:i:s');$onlineCut=date('Y-m-d H:i:s',time()-900);$fuelCut=date('Y-m-d H:i:s',time()-36*3600);
