 'clients'=>(int)epca_scalar("SELECT COUNT(*) FROM users WHERE role='client'"),
 'active_clients'=>(int)epca_scalar("SELECT COUNT(*) FROM users WHERE role='client' AND status='active'"),
 'online_devices'=>(int)epca_scalar('SELECT COUNT(*) FROM client_device_state WHERE last_seen_at>=?',[$onlineCut]),
 'live_events'=>(int)epca_scalar('SELECT COUNT(*) FROM road_live_events WHERE expires_at>?',[$now]),
 'traffic_samples'=>(int)epca_scalar('SELECT COUNT(*) FROM road_traffic_samples WHERE expires_at>?',[$now]),
 'weather_cache'=>(int)epca_scalar('SELECT COUNT(*) FROM road_weather_cache WHERE expires_at>?',[$now]),
 'fuel_reports'=>(int)epca_scalar('SELECT COUNT(*) FROM fuel_price_reports WHERE created_at>=?',[$fuelCut]),
 'hazards'=>(int)epca_scalar('SELECT COUNT(*) FROM road_hazards WHERE active=1'),
 'convoys'=>(int)epca_scalar('SELECT COUNT(*) FROM estrada_convoys WHERE expires_at>?',[$now]),
 'pending_reports'=>(int)($reportStats['pending']??0),
];
$clients=epca_rows("SELECT u.id,u.name,u.email,u.username,u.status,u.last_login_at,u.created_at,COUNT(d.id) devices,MAX(d.last_seen_at) last_device_seen FROM users u LEFT JOIN client_device_state d ON d.user_id=u.id WHERE u.role='client' GROUP BY u.id,u.name,u.email,u.username,u.status,u.last_login_at,u.created_at ORDER BY u.id DESC LIMIT 120");
$devices=epca_rows("SELECT d.*,u.name user_name,u.username FROM client_device_state d JOIN users u ON u.id=d.user_id ORDER BY d.last_seen_at DESC LIMIT 80");
