$live=epca_rows('SELECT id,user_id,event_type,latitude,longitude,road,note,confirmations,dismissals,heading,speed_kmh,expires_at,created_at,last_feedback_at FROM road_live_events WHERE expires_at>? ORDER BY created_at DESC LIMIT 100',[$now]);
$traffic=epca_rows("SELECT cell_key,MAX(COALESCE(road,'')) road,ROUND(AVG(speed_kmh),1) avg_speed,ROUND(AVG(COALESCE(limit_kmh,0)),1) avg_limit,COUNT(*) samples,MAX(updated_at) updated_at FROM road_traffic_samples WHERE expires_at>? GROUP BY cell_key ORDER BY samples DESC,updated_at DESC LIMIT 60",[$now]);
$weather=epca_rows('SELECT cache_key,latitude,longitude,fetched_at,expires_at FROM road_weather_cache ORDER BY fetched_at DESC LIMIT 50');
$fuel=epca_rows('SELECT id,user_id,station,fuel,price,latitude,longitude,reported_at,created_at FROM fuel_price_reports WHERE created_at>=? ORDER BY created_at DESC LIMIT 100',[$fuelCut]);
$hazardStats=road_hazard_stats();$hazardSync=road_hazard_sync_status();
$convoys=epca_rows("SELECT c.id,c.code,c.title,c.owner_user_id,c.created_at,c.expires_at,COUNT(m.device_token) members,MAX(m.last_seen) last_seen FROM estrada_convoys c LEFT JOIN estrada_convoy_members m ON m.convoy_id=c.id WHERE c.expires_at>? GROUP BY c.id,c.code,c.title,c.owner_user_id,c.created_at,c.expires_at ORDER BY c.created_at DESC LIMIT 50",[$now]);
$logs=epca_rows('SELECT action,payload,ip,created_at FROM audit_logs ORDER BY id DESC LIMIT 80');
$quota=(float)($health['quota_percent']??0);$quotaLevel=(string)($health['quota_level']??'ok');$csrf=csrf_token();
