<section id="usuarios" class="epc-section"><div class="epc-section-head"><div><h2>Usuários e aparelhos</h2><p>As mesmas contas usadas pelo aplicativo. Nenhum cadastro é duplicado.</p></div><input class="epc-input" data-user-filter placeholder="Filtrar usuário"></div><div class="epc-table-wrap"><table class="epc-table"><thead><tr><th>Cliente</th><th>Status</th><th>Dispositivos</th><th>Última atividade</th><th>Ações</th></tr></thead><tbody><?php if(!$clients):?><tr><td class="epc-empty" colspan="5">Nenhum cliente cadastrado.</td></tr><?php endif;?><?php foreach($clients as $c):$online=epca_online($c['last_device_seen']??null);?><tr data-user-row><td><strong><?=epca_e($c['name'])?></strong><br><span class="epc-muted"><?=epca_e($c['username'])?> · <?=epca_e($c['email'])?></span></td><td><span class="epc-badge <?=($c['status']==='active')?'ok':'bad'?>"><?=($c['status']==='active')?'ATIVO':'DESATIVADO'?></span> <?php if($online):?><span class="epc-badge cyan">ONLINE</span><?php endif;?></td><td><?=intval($c['devices'])?></td><td><?=epca_e($c['last_device_seen']?:($c['last_login_at']?:'Nunca'))?></td><td><div class="epc-inline"><form method="post"><input type="hidden" name="csrf" value="<?=epca_e($csrf)?>"><input type="hidden" name="action" value="toggle_client"><input type="hidden" name="client_id" value="<?=intval($c['id'])?>"><button class="epc-btn small" type="submit"><?=($c['status']==='active')?'Desativar':'Ativar'?></button></form><form method="post" class="epc-inline"><input type="hidden" name="csrf" value="<?=epca_e($csrf)?>"><input type="hidden" name="action" value="reset_password"><input type="hidden" name="client_id" value="<?=intval($c['id'])?>"><input class="epc-input compact" name="new_password" type="password" minlength="6" placeholder="Nova senha" required><button class="epc-btn small gold" type="submit">Redefinir</button></form></div></td></tr><?php endforeach;?></tbody></table></div>
<div class="epc-section-head" style="margin-top:22px"><div><h2>Aparelhos recentes</h2><p>Identificadores mascarados; localização e permissões permanecem ligadas ao usuário atual.</p></div></div><div class="epc-table-wrap"><table class="epc-table"><thead><tr><th>Usuário</th><th>Aparelho</th><th>Localização</th><th>Músicas</th><th>Último contato</th></tr></thead><tbody><?php foreach($devices as $d):?><tr><td><?=epca_e($d['user_name'])?><br><span class="epc-muted"><?=epca_e($d['username'])?></span></td><td><span class="epc-mono"><?=epca_e($d['device_name']?:epca_mask((string)$d['device_id']))?></span></td><td><?=epca_e($d['location_permission']??'unknown')?></td><td><?=epca_e($d['music_permission']??'unknown')?> · <?=intval($d['music_track_count']??0)?> faixas</td><td><span class="epc-badge <?=epca_online($d['last_seen_at']??null)?'ok':''?>"><?=epca_e($d['last_seen_at'])?></span></td></tr><?php endforeach;?></tbody></table></div></section>

<section id="estrada-viva" class="epc-section"><div class="epc-section-head"><div><h2>Estrada Viva e moderação</h2><p>Relatos do sistema e alertas comunitários do Server 7.0.</p></div></div><div class="epc-table-wrap"><table class="epc-table"><thead><tr><th>Relato</th><th>Local</th><th>Detalhes</th><th>Status</th><th>Moderação</th></tr></thead><tbody><?php if(!$reports):?><tr><td class="epc-empty" colspan="5">Nenhum relato técnico.</td></tr><?php endif;?><?php foreach($reports as $r):?><tr><td><strong>#<?=intval($r['id'])?> · <?=epca_e($r['type'])?></strong><br><span class="epc-muted"><?=epca_e($r['created_at'])?> · <?=epca_e($r['source'])?></span></td><td><a class="epc-coordinate" target="_blank" rel="noopener" href="<?=epca_e(epca_map((float)$r['latitude'],(float)$r['longitude']))?>"><?=number_format((float)$r['latitude'],5,',','')?>, <?=number_format((float)$r['longitude'],5,',','')?></a></td><td><?=epca_e($r['note']?:'—')?><?php if($r['limit_kmh']):?><br><span class="epc-muted">limite <?=intval($r['limit_kmh'])?> km/h</span><?php endif;?></td><td><span class="epc-badge <?=epca_status_class((string)$r['status'])?>"><?=epca_e($r['status'])?></span></td><td><div class="epc-inline"><?php foreach(['CONFIRMADO'=>'Confirmar','REJEITADO'=>'Rejeitar','PENDENTE'=>'Pendente'] as $st=>$lb):?><form method="post"><input type="hidden" name="csrf" value="<?=epca_e($csrf)?>"><input type="hidden" name="action" value="report_status"><input type="hidden" name="report_id" value="<?=intval($r['id'])?>"><input type="hidden" name="status" value="<?=$st?>"><button class="epc-btn small <?=$st==='CONFIRMADO'?'gold':($st==='REJEITADO'?'danger':'')?>" type="submit"><?=$lb?></button></form><?php endforeach;?></div></td></tr><?php endforeach;?></tbody></table></div>
<div class="epc-section-head" style="margin-top:22px"><div><h2>Alertas comunitários ativos</h2><p>Confirmações e descartes ajudam o app a calcular confiança.</p></div></div><div class="epc-table-wrap"><table class="epc-table"><thead><tr><th>Evento</th><th>Rodovia / local</th><th>Confiança comunitária</th><th>Validade</th><th>Ação</th></tr></thead><tbody><?php if(!$live):?><tr><td class="epc-empty" colspan="5">Nenhum alerta ativo agora.</td></tr><?php endif;?><?php foreach($live as $e):$positive=(int)$e['confirmations'];$negative=(int)$e['dismissals'];$score=($positive+1)/max(2,$positive+$negative+2);?><tr><td><strong>#<?=intval($e['id'])?> · <?=epca_e(epca_event_label((string)$e['event_type']))?></strong><br><span class="epc-muted"><?=epca_e($e['created_at'])?></span></td><td><?=epca_e($e['road']?:'Rodovia não informada')?><br><a class="epc-coordinate" target="_blank" rel="noopener" href="<?=epca_e(epca_map((float)$e['latitude'],(float)$e['longitude']))?>"><?=number_format((float)$e['latitude'],5,',','')?>, <?=number_format((float)$e['longitude'],5,',','')?></a></td><td><span class="epc-badge <?=$score>=.72?'ok':($score>=.5?'warn':'bad')?>"><?=number_format($score*100,0)?>%</span> <span class="epc-muted">+<?=$positive?> / -<?=$negative?></span></td><td><?=epca_e($e['expires_at'])?></td><td><form method="post" data-confirm="Remover este alerta comunitário agora?"><input type="hidden" name="csrf" value="<?=epca_e($csrf)?>"><input type="hidden" name="action" value="delete_live_event"><input type="hidden" name="event_id" value="<?=intval($e['id'])?>"><button class="epc-btn small danger" type="submit">Remover</button></form></td></tr><?php endforeach;?></tbody></table></div></section>

<section id="trafego-clima" class="epc-section"><div class="epc-section-head"><div><h2>Trânsito colaborativo</h2><p>Amostras opt-in, armazenadas somente com hash e retenção curta.</p></div></div><div class="epc-table-wrap"><table class="epc-table"><thead><tr><th>Trecho</th><th>Rodovia</th><th>Velocidade média</th><th>Amostras</th><th>Atualização</th></tr></thead><tbody><?php if(!$traffic):?><tr><td class="epc-empty" colspan="5">Sem amostras de trânsito ativas.</td></tr><?php endif;?><?php foreach($traffic as $t):$avg=(float)$t['avg_speed'];$limit=(float)$t['avg_limit'];$level=$avg<10?'PARADO':($avg<25?'MUITO LENTO':($avg<45?'LENTO':($avg<65?'MODERADO':'LIVRE')));?><tr><td><span class="epc-mono"><?=epca_e($t['cell_key'])?></span></td><td><?=epca_e($t['road']?:'—')?></td><td><strong><?=number_format($avg,1,',','')?> km/h</strong> <span class="epc-badge <?=epca_status_class($level)?>"><?=$level?></span><?php if($limit>0):?><br><span class="epc-muted">limite médio <?=number_format($limit,0)?> km/h</span><?php endif;?></td><td><?=intval($t['samples'])?></td><td><?=epca_e($t['updated_at'])?></td></tr><?php endforeach;?></tbody></table></div>
<div class="epc-section-head" style="margin-top:22px"><div><h2>Cache meteorológico</h2><p>O clima de rota é reaproveitado por 15 minutos para reduzir chamadas externas.</p></div><form method="post" data-confirm="Limpar todo o cache meteorológico?"><input type="hidden" name="csrf" value="<?=epca_e($csrf)?>"><input type="hidden" name="action" value="clear_weather"><button class="epc-btn small danger" type="submit">Limpar cache</button></form></div><div class="epc-table-wrap"><table class="epc-table"><thead><tr><th>Chave</th><th>Ponto</th><th>Coletado</th><th>Expira</th></tr></thead><tbody><?php if(!$weather):?><tr><td class="epc-empty" colspan="4">Cache vazio.</td></tr><?php endif;?><?php foreach($weather as $w):?><tr><td><span class="epc-mono"><?=epca_e($w['cache_key'])?></span></td><td><a class="epc-coordinate" target="_blank" rel="noopener" href="<?=epca_e(epca_map((float)$w['latitude'],(float)$w['longitude']))?>"><?=number_format((float)$w['latitude'],4,',','')?>, <?=number_format((float)$w['longitude'],4,',','')?></a></td><td><?=epca_e($w['fetched_at'])?></td><td><span class="epc-badge <?=strtotime((string)$w['expires_at'])>time()?'ok':'bad'?>"><?=epca_e($w['expires_at'])?></span></td></tr><?php endforeach;?></tbody></table></div></section>

<section id="combustivel" class="epc-section"><div class="epc-section-head"><div><h2>Combustível comunitário</h2><p>Preços informados nas últimas 36 horas, usando o mesmo ranking de rota do aplicativo.</p></div></div><div class="epc-table-wrap"><table class="epc-table"><thead><tr><th>Posto</th><th>Combustível</th><th>Preço</th><th>Local</th><th>Informado</th><th>Ação</th></tr></thead><tbody><?php if(!$fuel):?><tr><td class="epc-empty" colspan="6">Nenhum preço recente.</td></tr><?php endif;?><?php foreach($fuel as $f):?><tr><td><strong><?=epca_e($f['station'])?></strong></td><td><span class="epc-badge gold"><?=epca_e(strtoupper((string)$f['fuel']))?></span></td><td><strong>R$ <?=number_format((float)$f['price'],3,',','.')?></strong></td><td><a class="epc-coordinate" target="_blank" rel="noopener" href="<?=epca_e(epca_map((float)$f['latitude'],(float)$f['longitude']))?>"><?=number_format((float)$f['latitude'],5,',','')?>, <?=number_format((float)$f['longitude'],5,',','')?></a></td><td><?=epca_e($f['created_at'])?></td><td><form method="post" data-confirm="Remover este preço informado?"><input type="hidden" name="csrf" value="<?=epca_e($csrf)?>"><input type="hidden" name="action" value="delete_fuel"><input type="hidden" name="fuel_id" value="<?=intval($f['id'])?>"><button class="epc-btn small danger" type="submit">Remover</button></form></td></tr><?php endforeach;?></tbody></table></div></section>

<section id="radares" class="epc-section"><div class="epc-section-head"><div><h2>Radares e base rodoviária</h2><p>Resumo da base unificada. A edição detalhada continua disponível na Central de Radares.</p></div><a class="epc-btn gold" href="admin_radares.php">Abrir Central de Radares</a></div><?php $maxHaz=max(1,...array_values($hazardStats?:['OUTRO'=>1]));?><div class="epc-barlist"><?php if(!$hazardStats):?><div class="epc-muted">Nenhum ponto carregado.</div><?php endif;?><?php foreach($hazardStats as $type=>$count):?><div class="epc-bar-row"><span><?=epca_e($type)?></span><div class="epc-bar"><span style="width:<?=max(2,($count/$maxHaz)*100)?>%"></span></div><strong><?=intval($count)?></strong></div><?php endforeach;?></div><div class="epc-section-head" style="margin-top:22px"><div><h2>Sincronização por estado</h2><p>SP, RJ, MG e ES usam a mesma tabela road_hazards.</p></div></div><div class="epc-table-wrap"><table class="epc-table"><thead><tr><th>UF</th><th>Itens</th><th>Última tentativa</th><th>Último sucesso</th><th>Erro</th></tr></thead><tbody><?php foreach($hazardSync as $s):?><tr><td><strong><?=epca_e($s['uf'])?></strong></td><td><?=intval($s['item_count'])?></td><td><?=epca_e($s['last_attempt']?:'—')?></td><td><span class="epc-badge <?=$s['last_success']?'ok':'warn'?>"><?=epca_e($s['last_success']?:'Nunca')?></span></td><td class="epc-muted"><?=epca_e($s['last_error']?:'—')?></td></tr><?php endforeach;?></tbody></table></div></section>

<section id="comboios" class="epc-section"><div class="epc-section-head"><div><h2>Comboios ativos</h2><p>Grupos temporários e quantidade de participantes registrados no mesmo banco.</p></div></div><div class="epc-table-wrap"><table class="epc-table"><thead><tr><th>Código</th><th>Título</th><th>Membros</th><th>Criado</th><th>Expira</th><th>Ação</th></tr></thead><tbody><?php if(!$convoys):?><tr><td class="epc-empty" colspan="6">Nenhum comboio ativo.</td></tr><?php endif;?><?php foreach($convoys as $c):?><tr><td><strong class="epc-mono"><?=epca_e($c['code'])?></strong></td><td><?=epca_e($c['title']?:'Comboio Estrada Play')?></td><td><span class="epc-badge cyan"><?=intval($c['members'])?> membros</span></td><td><?=epca_e($c['created_at'])?></td><td><?=epca_e($c['expires_at'])?></td><td><form method="post" data-confirm="Encerrar este comboio e remover os membros ativos?"><input type="hidden" name="csrf" value="<?=epca_e($csrf)?>"><input type="hidden" name="action" value="close_convoy"><input type="hidden" name="convoy_id" value="<?=intval($c['id'])?>"><button class="epc-btn small danger" type="submit">Encerrar</button></form></td></tr><?php endforeach;?></tbody></table></div></section>

<section id="servidor" class="epc-section"><div class="epc-section-head"><div><h2>Servidor e manutenção</h2><p>Diagnóstico sem armazenar áudio ou vídeo. Ações abaixo operam no mesmo banco atual.</p></div><div class="epc-section-actions"><form method="post"><input type="hidden" name="csrf" value="<?=epca_e($csrf)?>"><input type="hidden" name="action" value="housekeeping"><button class="epc-btn gold" type="submit">Executar housekeeping</button></form><a class="epc-btn" href="admin_server.php">Diagnóstico completo</a></div></div><div class="epc-grid"><article class="epc-card"><span class="label">Servidor</span><div class="metric" style="font-size:20px"><?=epca_e(ESTRADAPLAY_SERVER_INTELLIGENT_VERSION)?></div><div class="sub">contexto de rota ativo</div></article><article class="epc-card"><span class="label">Banco</span><div class="metric" style="font-size:20px"><?=epca_e($health['db_h']??'0 B')?></div><div class="sub"><?=epca_e((string)db()->getAttribute(PDO::ATTR_DRIVER_NAME))?></div></article><article class="epc-card"><span class="label">Logs</span><div class="metric" style="font-size:20px"><?=epca_e($health['logs_h']??'0 B')?></div><div class="sub">rotação automática</div></article><article class="epc-card"><span class="label">Catálogo</span><div class="metric" style="font-size:20px"><?=intval($health['tracks']??0)?></div><div class="sub">metadados musicais</div></article></div><p class="epc-muted" style="margin-top:14px">Última sincronização do catálogo: <?=epca_e($health['last_sync']??'Nunca')?> · Pastas ativas: <?=intval($health['active_roots']??0)?> · Contexto: <?=intval($contextStats['active_live_events']??0)?> alertas / <?=intval($contextStats['active_traffic_samples']??0)?> amostras / <?=intval($contextStats['weather_cache_entries']??0)?> caches.</p></section>

<section id="auditoria" class="epc-section"><div class="epc-section-head"><div><h2>Auditoria</h2><p>Últimas ações administrativas e operações relevantes registradas pelo backend.</p></div></div><?php if(!$logs):?><div class="epc-muted">Nenhum registro.</div><?php endif;?><?php foreach($logs as $l):?><div class="epc-log"><span><?=epca_e($l['created_at'])?></span><strong><?=epca_e($l['action'])?></strong><code><?=epca_e($l['payload']?:'{}')?></code></div><?php endforeach;?></section>
